from mlp.models import SingleLayerModel, MultipleLayerModel
from mlp.layers import Layer, LayerWithParameters, StochasticLayer

class AddParamLayer(LayerWithParameters):
    def __init__(self, value):
        self.w = np.array([value], dtype=float)
    def fprop(self, inputs):
        return inputs + self.w
    def bprop(self, inputs, outputs, grads_wrt_outputs):
        return grads_wrt_outputs
    def grads_wrt_params(self, inputs, grads_wrt_outputs):
        return [grads_wrt_outputs.sum(axis=0)]
    def params_penalty(self):
        return float(self.w.sum())
    @property
    def params(self):
        return [self.w]
    @params.setter
    def params(self, values):
        self.w = values[0]

class TimesTwo(Layer):
    def fprop(self, inputs):
        return 2 * inputs
    def bprop(self, inputs, outputs, grads_wrt_outputs):
        return 2 * grads_wrt_outputs

class MaybeAddOne(StochasticLayer):
    def fprop(self, inputs, stochastic=True):
        return inputs + (1 if stochastic else 0)
    def bprop(self, inputs, outputs, grads_wrt_outputs):
        return grads_wrt_outputs

